def A(name, cyr, region_, summ, extra_match=(), **kw):
    kw.setdefault("styles", ["red", "white"])
    kw.setdefault("created", "EU PDO 2007")
    return app(I, name, [cyr] + list(extra_match), "PDO", region_, summ, **kw)

